from dataclasses import dataclass, field
from datetime import datetime

@dataclass
class Task:
    title: str
    priority: int = 3
    tags: list[str] = field(default_factory=list)
    created: datetime = field(default_factory=datetime.now)

a, b = Task("write docs"), Task("fix bug", priority=1)
a.tags.append("docs")
print(a.tags, b.tags)              # ['docs'] []   (separate lists)
print(b.priority, Task.priority)   # 1 3

try:
    @dataclass
    class Bad:
        items: list[int] = []
except ValueError as e:
    print(e)   # mutable default <class 'list'> for field items is not allowed: use default_factory

from dataclasses import dataclass, field

@dataclass
class LineItem:
    sku: str
    price: float
    quantity: int = 1
    total: float = field(init=False)

    def __post_init__(self):
        self.sku = self.sku.strip().upper()
        if self.quantity < 1:
            raise ValueError(f"quantity must be >= 1, got {self.quantity}")
        self.total = round(self.price * self.quantity, 2)

item = LineItem(" ab-12 ", 9.99, 3)
print(item)          # LineItem(sku='AB-12', price=9.99, quantity=3, total=29.97)
try:
    LineItem("x", 1.0, 0)
except ValueError as e:
    print(e)         # quantity must be >= 1, got 0
item.quantity = 0    # not validated after construction!

from dataclasses import dataclass, field, fields

@dataclass
class DbConfig:
    host: str = field(metadata={"env": "DB_HOST"})
    port: int = field(default=5432, metadata={"env": "DB_PORT"})
    password: str = field(default="", repr=False, metadata={"env": "DB_PASSWORD"})
    _cache: dict = field(default_factory=dict, repr=False, compare=False)

cfg = DbConfig("db.local", password="s3cret")
print(cfg)                          # DbConfig(host='db.local', port=5432)  (no password)
cfg._cache["x"] = 1
print(cfg == DbConfig("db.local", password="s3cret"))   # True: _cache not compared

def from_env(env: dict[str, str]) -> DbConfig:
    kwargs = {f.name: f.type(env[f.metadata["env"]])
              for f in fields(DbConfig) if f.metadata.get("env") in env}
    return DbConfig(**kwargs)

print(from_env({"DB_HOST": "prod", "DB_PORT": "6543"}))  # DbConfig(host='prod', port=6543)

import json
from dataclasses import asdict, astuple, dataclass, field, replace

@dataclass
class Address:
    city: str
    zip: str | None = None

@dataclass
class User:
    name: str
    address: Address
    roles: list[str] = field(default_factory=list)

u = User("ada", Address("London"), ["admin"])
print(asdict(u))
# {'name': 'ada', 'address': {'city': 'London', 'zip': None}, 'roles': ['admin']}
print(astuple(u))                       # ('ada', ('London', None), ['admin'])
no_none = asdict(u.address, dict_factory=lambda kv: {k: v for k, v in kv if v is not None})
print(json.dumps(no_none))              # {"city": "London"}

moved = replace(u, address=Address("Paris", "75001"))
print(moved.address.city, u.address.city)   # Paris London
print(User(**{"name": "bob", "address": Address("Rome")}))

import sys
from dataclasses import dataclass, KW_ONLY
@dataclass
class PlainPoint:
    x: float; y: float

@dataclass(slots=True)
class SlotPoint:
    x: float; y: float

p, s = PlainPoint(1, 2), SlotPoint(1, 2)
print(hasattr(p, "__dict__"), hasattr(s, "__dict__"))   # True False
print(sys.getsizeof(p) + sys.getsizeof(p.__dict__), sys.getsizeof(s))  # e.g. 344 48
try:
    s.z = 3
except AttributeError as e:
    print("typo caught:", e)        # 'SlotPoint' object has no attribute 'z' ...

@dataclass
class Request:
    url: str
    _: KW_ONLY
    timeout: float = 10.0
    retries: int                    # required, allowed after a default because kw-only
print(Request("https://x.io", retries=2))   # Request(url='https://x.io', timeout=10.0, retries=2)

from dataclasses import dataclass, field
from datetime import datetime

@dataclass
class Entity:
    id: int
    created: datetime = field(default_factory=lambda: datetime(2026, 1, 1))

    def __post_init__(self):
        if self.id <= 0:
            raise ValueError("id must be positive")

@dataclass(kw_only=True)
class User(Entity):
    name: str                       # required, but keyword-only: no ordering error
    email: str = ""

    def __post_init__(self):
        super().__post_init__()     # not called automatically
        self.email = self.email.lower()

u = User(7, name="Ada", email="ADA@X.IO")
print(u)   # User(id=7, created=datetime.datetime(2026, 1, 1, 0, 0), name='Ada', email='ada@x.io')
print(u == Entity(7))               # False: different classes

from dataclasses import dataclass

@dataclass
class Mutable: x: int
@dataclass(frozen=True)
class Frozen: x: int
@dataclass(unsafe_hash=True)
class Risky: x: int

print(Mutable.__hash__)                 # None -> unhashable
print(hash(Frozen(1)) == hash(Frozen(1)))   # True

r = Risky(1)
bucket = {r}
r.x = 2                                 # mutate after hashing...
print(r in bucket, Risky(2) in bucket)  # False False  -> object lost in its own set

@dataclass(frozen=True)
class WithList: items: list
try:
    hash(WithList([1]))
except TypeError as e:
    print(e)                            # unhashable type: 'list'

from dataclasses import dataclass
from typing import NamedTuple, TypedDict, dataclass_transform

@dataclass(frozen=True, slots=True)
class PointDC:
    x: int; y: int

class PointNT(NamedTuple):
    x: int; y: int

class PointTD(TypedDict):
    x: int; y: int

print(PointDC(1, 2) == (1, 2), PointNT(1, 2) == (1, 2))   # False True
x, y = PointNT(3, 4)                                       # tuple unpacking works
print(x, PointTD(x=1, y=2))                                # 3 {'x': 1, 'y': 2}

@dataclass_transform()
def model(cls):                    # checkers now treat @model classes like dataclasses
    return dataclass(cls)

@model
class User:
    name: str
print(User(name="ada"))            # User(name='ada')
